  grammar: {
    title: 'Regular Simple Past Verbs (-ed) & Past Time Expressions',
    concept: 'Forming positive statements with regular past verbs (-ed / -d) and using past time markers',
    patterns: [
      {
        title: 'Regular Past Verb Spelling Rules',
        structure: 'Subject + [Verb-ed] + Object/Details + Past Time Marker',
        rule: 'Most verbs: add -ed (work -> worked, visit -> visited). Verbs ending in -e: add -d (live -> lived, dance -> danced). Verbs ending in consonant + y: change y to -ied (study -> studied, carry -> carried). 1-syllable verbs ending in consonant-vowel-consonant: double the consonant (stop -> stopped, plan -> planned).',
        examples: [
          { en: 'I studied English for two hours yesterday.', hi: 'मैंने कल दो घंटे अंग्रेजी की पढ़ाई की।', es: 'Estudié inglés durante dos horas ayer.' },
          { en: 'We planned our summer holiday last night.', hi: 'हमने कल रात अपनी गर्मियों की छुट्टियों की योजना बनाई।', es: 'Planeamos nuestras vacaciones de verano anoche.' }
        ]
      },
      {
        title: 'Pronunciation of -ed: /t/, /d/, and /ɪd/',
        structure: 'Voiceless sound + /t/ | Voiced sound + /d/ | /t/ or /d/ ending + /ɪd/',
        rule: '1) /t/ after voiceless sounds (p, k, f, s, sh, ch): watched /wɑːtʃt/, cooked /kʊkt/, worked /wɝːkt/. 2) /d/ after voiced sounds (vowels, b, g, v, z, m, n, l, r): played /pleɪd/, lived /lɪvd/, cleaned /kliːnd/. 3) /ɪd/ after root verbs ending in T or D: visited /ˈvɪz.ɪ.tɪd/, waited /ˈweɪ.t̬ɪd/, started /ˈstɑːr.t̬ɪd/.',
        examples: [
          { en: 'They waited for thirty minutes at the station.', hi: 'उन्होंने स्टेशन पर तीस मिनट तक इंतजार किया।', es: 'Esperaron durante treinta minutos en la estación.' },
          { en: 'She cleaned her room and listened to music.', hi: 'उसने अपना कमरा साफ किया और संगीत सुना।', es: 'Ella limpió su habitación y escuchó música.' }
        ]
      }
    ]
  },
  mistakes: [
    { inc: 'I work yesterday at the store.', cor: 'I worked yesterday at the store.', exp: 'Past events require the past tense form (worked), not present simple (work).', hi: 'भूतकाल की क्रिया के लिए "-ed" लगाना आवश्यक है (worked), "work" नहीं।', es: 'Las acciones pasadas requieren la terminación en pasado (worked), no el presente (work).' },
    { inc: 'She visit me two days before.', cor: 'She visited me two days ago.', exp: 'Use "ago" after a time duration to count back from the present (two days ago).', hi: 'वर्तमान से पहले के समय के लिए "two days ago" कहें, "two days before" नहीं।', es: 'Usa "two days ago" (hace dos días), no "two days before".' },
    { inc: 'We stayied in a nice hotel.', cor: 'We stayed in a nice hotel.', exp: 'Verbs ending in vowel + y simply add -ed (stay -> stayed, play -> played); do not drop the y.', hi: 'स्वर + y वाले शब्दों में केवल -ed जोड़ें (stayed), "stayied" गलत है।', es: 'Los verbos que terminan en vocal + y solo añaden -ed (stayed, played).' },
    { inc: 'I stoped the car at the red light.', cor: 'I stopped the car at the red light.', exp: 'Short consonant-vowel-consonant verbs double the final consonant (stop -> stopped).', hi: 'एक शब्दांश वाले क्रिया में अंतिम व्यंजन दोहराया जाता है (stop -> stopped)।', es: 'Los verbos cortos CVC doblan la última consonante (stop -> stopped).' },
    { inc: 'He lived here in last year.', cor: 'He lived here last year.', exp: 'Do not use prepositions like "in" or "on" before "last week", "last year", or "yesterday".', hi: '"last year" या "yesterday" से पहले "in" या "on" का प्रयोग न करें।', es: 'No uses "in" ni "on" delante de "last year", "last week" ni "yesterday".' }
  ],
